(() => {
  const doc = document.documentElement;
  const body = document.body;
  const menuToggle = document.getElementById("menuToggle");
  const navLinks = document.getElementById("navLinks");
  const themeToggle = document.getElementById("themeToggle");
  const reviewForms = document.querySelectorAll(".review-form");
  const reviewLists = document.querySelectorAll(".reviews-list");
  const pairSliders = document.querySelectorAll("[data-work-pair-slider]");
  const isLocalHost = ["localhost", "127.0.0.1"].includes(location.hostname);
  const isStaticPreview =
    location.protocol === "file:" ||
    (isLocalHost && location.port !== "3000");
  const apiEndpoints = isLocalHost && location.port === "3000" ? ["/api/reviews"] : [];
  const defaultReviews = [];
  const deletedReviews = [
    ["خالد", "مشاء الله عليكم"],
    ["احمد الشرقاوي", "افضل تعامل بصراحه وسرعه وافضل سعر شوفته ما شاء الله عليكم"]
  ];

  const setTheme = (theme) => {
    const next = theme === "light" ? "light" : "dark";
    if (!body) return;
    body.dataset.theme = next;
    localStorage.setItem("siteTheme", next);
    if (themeToggle) {
      themeToggle.setAttribute("aria-pressed", String(next === "light"));
      themeToggle.title = next === "light" ? "Dark Mode" : "Light Mode";
    }
  };

  const escapeHtml = (value) =>
    String(value).replace(/[&<>"']/g, (char) => ({
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;",
      "\"": "&quot;",
      "'": "&#39;"
    }[char]));

  const isDeletedReview = (review) =>
    deletedReviews.some(([name, message]) =>
      String(review.name || "").trim() === name &&
      String(review.message || "").trim() === message
    );

  const normalizeReviews = (reviews) =>
    (Array.isArray(reviews) && reviews.length ? reviews : defaultReviews)
      .filter((review) => review && review.name && review.message && !isDeletedReview(review))
      .slice(0, 50);

  const renderReviews = (reviews) => {
    const items = normalizeReviews(reviews);
    const html = items.map((review) => `
      <article class="review-card">
        <strong>${escapeHtml(review.name)}</strong>
        <p><span aria-hidden="true">💬</span><span class="sr-only">رسالة</span>${escapeHtml(review.message)}</p>
      </article>
    `).join("");
    reviewLists.forEach((list) => {
      list.innerHTML = html;
    });
  };

  const requestReviews = async (endpoint, options = {}) => {
    const response = await fetch(endpoint, {
      cache: "no-store",
      headers: { "Content-Type": "application/json" },
      ...options
    });
    if (!response.ok) throw new Error("reviews request failed");
    return response.json();
  };

  const loadReviews = async () => {
    for (const endpoint of apiEndpoints) {
      try {
        const reviews = await requestReviews(endpoint);
        renderReviews(reviews);
        return endpoint;
      } catch {
        // Try the next endpoint, then fall back to local rendering.
      }
    }
    const local = JSON.parse(localStorage.getItem("customerReviews") || "[]");
    renderReviews(local.length ? local : defaultReviews);
    return "";
  };

  const saveReview = async (review) => {
    for (const endpoint of apiEndpoints) {
      try {
        const reviews = await requestReviews(endpoint, {
          method: "POST",
          body: JSON.stringify(review)
        });
        renderReviews(reviews);
        return true;
      } catch {
        // Try the next endpoint.
      }
    }
    const local = normalizeReviews(JSON.parse(localStorage.getItem("customerReviews") || "[]"));
    const reviews = [review, ...local].slice(0, 50);
    localStorage.setItem("customerReviews", JSON.stringify(reviews));
    renderReviews(reviews);
    return false;
  };

  setTheme(localStorage.getItem("siteTheme") || body?.dataset.theme || "dark");

  if (themeToggle) {
    themeToggle.addEventListener("click", () => {
      setTheme(body.dataset.theme === "light" ? "dark" : "light");
    });
  }

  if (menuToggle && navLinks) {
    menuToggle.addEventListener("click", () => {
      const open = navLinks.classList.toggle("open");
      body.classList.toggle("menu-open", open);
      menuToggle.setAttribute("aria-expanded", String(open));
    });

    navLinks.addEventListener("click", (event) => {
      if (!event.target.closest("a")) return;
      navLinks.classList.remove("open");
      body.classList.remove("menu-open");
      menuToggle.setAttribute("aria-expanded", "false");
    });
  }

  const revealEls = document.querySelectorAll(".reveal");
  if ("IntersectionObserver" in window) {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        entry.target.classList.add("visible");
        observer.unobserve(entry.target);
      });
    }, { threshold: 0.12 });
    revealEls.forEach((el) => observer.observe(el));
  } else {
    revealEls.forEach((el) => el.classList.add("visible"));
  }

  document.querySelectorAll('a[href^="#"]').forEach((link) => {
    link.addEventListener("click", (event) => {
      const target = document.querySelector(link.getAttribute("href"));
      if (!target) return;
      event.preventDefault();
      target.scrollIntoView({ behavior: "smooth", block: "start" });
    });
  });

  pairSliders.forEach((slider, index) => {
    const images = slider.querySelectorAll(".work-pair-image");
    if (images.length < 2) return;
    let activeIndex = 0;
    window.setInterval(() => {
      images[activeIndex].classList.remove("active");
      activeIndex = (activeIndex + 1) % images.length;
      images[activeIndex].classList.add("active");
    }, 3200 + (index % 5) * 220);
  });

  reviewForms.forEach((form) => {
    form.addEventListener("submit", async (event) => {
      event.preventDefault();
      const button = form.querySelector("button");
      const formData = new FormData(form);
      const review = {
        name: String(formData.get("name") || "").trim(),
        message: String(formData.get("message") || "").trim()
      };

      if (!review.name || !review.message) return;
      if (button) {
        button.disabled = true;
        button.textContent = "جاري الإرسال...";
      }

      await saveReview(review);
      form.reset();

      if (button) {
        button.disabled = false;
        button.textContent = "إرسال الرأي";
      }
    });
  });

  renderReviews(defaultReviews);
  if (reviewLists.length || reviewForms.length) {
    loadReviews();
  }
  doc.classList.add("js-ready");
})();
